240: function disposeObject(obj, keepPersistent = true) {
241:   obj.traverse((o) => {
242:     if (o.isMesh || o.isPoints || o.isSprite) {
243:       if (o.geometry && !o.geometry.userData.persistent) o.geometry.dispose?.();
244:       const mats = Array.isArray(o.material) ? o.material : [o.material];
245:       for (const m of mats) {
246:         if (!m || m.userData.persistent) continue;
247:         for (const k of Object.keys(m)) {
248:           const v = m[k];
249:           if (v && v.isTexture && !v.userData?.persistent) v.dispose?.();
250:         }
251:         m.dispose?.();
252:       }
253:     }
254:   });
255: }
