840: function updatePlayer(game, dt) {
841:   const p = game.player;
842:   const c = controls();
843:   const track = game.track;
844:   const halfW = track.halfWidth;
845:   const n = track.nearest(p.pos, p.hintIdx);
846:   p.hintIdx = n.idx;
847:   p.lateral = n.lateral;
848:   p.offroad = Math.abs(n.lateral) > halfW - 0.2;
849: 
850:   // steering smoothing
851:   const steerTarget = c.steer;
852:   p.steerVis = damp(p.steerVis, steerTarget, steerTarget !== 0 ? 8 : 11, dt);
853: 
854:   const speed = p.vel.length();
855:   const fwd = new THREE.Vector2(-Math.sin(p.yaw), -Math.cos(p.yaw));
856:   const right = new THREE.Vector2(Math.cos(p.yaw), -Math.sin(p.yaw));
857:   let vf = p.vel.dot(fwd);
858:   let vl = p.vel.dot(right);
859: 
860:   // engine
861:   const maxSpeed = c.nitro && p.nitro > 0.01 && vf > 4 ? 76 : 63;
862:   const speedRatio = clamp(vf / maxSpeed, 0, 1);
863:   let accel = 0;
864:   if (c.throttle) {
865:     accel = 23.5 * Math.pow(1 - speedRatio, 0.55) + 4.2;
866:     if (p.offroad) accel *= 0.34;
867:   }
868:   if (c.nitro && p.nitro > 0.01 && vf > 4) {
869:     accel += 15.5 * Math.pow(1 - speedRatio * 0.7, 0.8);
870:     p.nitro = Math.max(0, p.nitro - dt * 0.27);
871:     p.boost = true;
872:   } else {
873:     p.boost = false;
874:     p.nitro = Math.min(1, p.nitro + dt * 0.055);
875:   }
876:   if (c.brake) {
877:     if (vf > 0.5) accel -= 42;
878:     else if (!c.throttle) accel -= 7;
879:   }
880:   // coast / drag
881:   accel -= vf * Math.abs(vf) * 0.0022 + Math.sign(vf) * 0.55;
882:   if (p.offroad) accel -= vf * 0.55;
883: 
884:   vf += accel * dt;
885:   vf = clamp(vf, -9, maxSpeed);
886: 
887:   // lateral grip (drift feel off-road and at speed)
888:   const grip = p.offroad ? 2.2 : 7.2;
889:   vl *= Math.exp(-grip * dt);
890: 
891:   // steering
892:   const steerAuthority = lerp(2.25, 0.92, clamp(Math.abs(vf) / 68, 0, 1));
893:   const turn = p.steerVis * steerAuthority * (p.offroad ? 0.7 : 1);
894:   if (Math.abs(vf) > 0.6) p.yaw += turn * dt * Math.sign(vf);
895:   // cornering scrub
896:   vf *= 1 - Math.min(0.5, Math.abs(p.steerVis) * clamp(Math.abs(vf) / 63, 0, 1) * 0.42) * dt;
897: 
898:   // rebuild velocity
899:   p.vel.set(fwd.x * vf + right.x * vl, fwd.y * vf + right.y * vl);
900:   p.speed = p.vel.length();
901:   p.lean = damp(p.lean, clamp(p.steerVis * 0.52 * clamp(p.speed / 22, 0, 1), -0.62, 0.62), 8, dt);
902:   const targetPitch = c.brake && p.speed > 4 ? -0.035 : (p.boost ? 0.055 : 0.005 * Math.sin(game.raceTime * 9));
903:   p.pitch = damp(p.pitch, targetPitch, 6, dt);
904: 
905:   // move
906:   p.pos.x += p.vel.x * dt;
907:   p.pos.z += p.vel.y * dt;
908: 
909:   // barrier / edge containment
910:   if (Math.abs(n.lateral) > halfW + 6.1) {
911:     const push = Math.abs(n.lateral) - (halfW + 6.1);
912:     const dir = -Math.sign(n.lateral);
913:     p.pos.addScaledVector(new THREE.Vector3(n.idx >= 0 ? track.samples[n.idx].r.x : 0, 0, n.idx >= 0 ? track.samples[n.idx].r.z : 0), dir * push);
914:     const impact = Math.min(1, p.speed / 28);
915:     if (impact > 0.15 && p.speed > 6) {
916:       p.vel.multiplyScalar(0.72);
917:       p.speed *= 0.72;
918:       game.shake = Math.min(0.9, impact * 0.8);
919:       state.audio.crash();
920:       spawnSparks(game, p.pos, 10);
921:     }
922:   }
923:   p.skid = Math.abs(p.steerVis) * clamp(p.speed / 55, 0, 1) * 0.8;
924: }
