926: function updateAI(game, r, dt) {
927:   const track = game.track;
928:   const n = track.nearest(r.pos, r.hintIdx);
929:   r.hintIdx = n.idx;
930:   r.lateral = n.lateral;
931: 
932:   if (game.raceTime < r.reaction) return;
933: 
934:   const speed = r.speed;
935:   const halfW = track.halfWidth;
936:   const look = 15 + speed * 0.62;
937:   const ahead = track.pointAt(n.s + look);
938: 
939:   // lane offset drifts gently, bots take slightly different lines
940:   const lane = r.lineOffset + Math.sin(game.raceTime * 0.35 + r.phase) * 0.85;
941: 
942:   // avoid the bike in front
943:   let avoid = 0;
944:   let closest = Infinity;
945:   for (const o of game.racers) {
946:     if (o === r) continue;
947:     const dx = o.pos.x - r.pos.x, dz = o.pos.z - r.pos.z;
948:     const d2 = dx * dx + dz * dz;
949:     if (d2 < 220 && d2 > 0.01) {
950:       const fwd = new THREE.Vector3(-Math.sin(r.yaw), 0, -Math.cos(r.yaw));
951:       const dot = (dx * fwd.x + dz * fwd.z) / Math.sqrt(d2);
952:       if (dot > 0.55) {
953:         const lat = dx * Math.cos(r.yaw) - dz * Math.sin(r.yaw);
954:         if (Math.abs(lat) < 2.4) {
955:           avoid -= Math.sign(lat || 1) * (2.6 - Math.abs(lat)) * 1.2;
956:         }
957:         if (d2 < closest) closest = d2;
958:       }
959:     }
960:   }
961:   avoid = clamp(avoid, -3.2, 3.2);
962:   const target = ahead.p.clone().addScaledVector(ahead.r, clamp(lane + avoid, -halfW + 1.6, halfW - 1.6));
963: 
964:   let dx = target.x - r.pos.x;
965:   let dz = target.z - r.pos.z;
966:   let desired = Math.atan2(-dx, -dz);
967:   let diff = desired - r.yaw;
968:   diff = Math.atan2(Math.sin(diff), Math.cos(diff));
969:   const maxTurn = Math.min(2.0, 22 / Math.max(8, speed));
970:   r.yaw += clamp(diff * 5.5, -maxTurn, maxTurn) * dt;
971: 
972:   // corner speed from lookahead
973:   let cornerLimit = 999;
974:   const skill = r.skill;
975:   const latAccel = 21.8 * skill;
976:   const N = track.count;
977:   const baseIdx = n.idx;
978:   for (let m = 14; m < 150; m += 10) {
979:     const idx = (baseIdx + m) % N;
980:     const curv = Math.max(track.samples[idx].curv, 0.0007);
981:     const lim = Math.sqrt(latAccel / curv) * 0.94;
982:     if (lim < cornerLimit) cornerLimit = lim;
983:   }
984:   const vmax = (52.5 + skill * 5.4) * (0.975 + Math.min(0.05, Math.max(0, (game.raceTime - 3) * 0.004)));
985:   // mild rubber-band
986:   let band = 1;
987:   const gap = r.progress - game.player.progress;
988:   if (gap < -120) band = 1.035;
989:   else if (gap > 110) band = 0.975;
990:   let targetSpeed = Math.min(vmax * band, Math.max(14, cornerLimit));
991:   if (closest < 55) targetSpeed *= 0.96;
992:   if (r.finished) targetSpeed = Math.min(targetSpeed, 26);
993: 
994:   // accelerate / brake
995:   const accel = targetSpeed > speed ? 19 * (1 - speed / 85) + 4 : -24;
996:   r.speed = clamp(speed + accel * dt, 0, 82);
997: 
998:   // move
999:   const fwd = new THREE.Vector2(-Math.sin(r.yaw), -Math.cos(r.yaw));
1000:   r.pos.x += fwd.x * r.speed * dt;
1001:   r.pos.z += fwd.y * r.speed * dt;
