743:     nearest(pos, hint = -1) {
744:       let bestIdx = 0, bestDist = Infinity;
745:       if (hint < 0) {
746:         for (let i = 0; i < count; i++) {
747:           const d = samples[i].p.distanceToSquared(pos);
748:           if (d < bestDist) { bestDist = d; bestIdx = i; }
749:         }
750:       } else {
751:         for (let k = -45; k <= 45; k++) {
752:           const i = (hint + k + count) % count;
753:           const d = samples[i].p.distanceToSquared(pos);
754:           if (d < bestDist) { bestDist = d; bestIdx = i; }
755:         }
756:       }
757:       const s = samples[bestIdx];
758:       const d = pos.clone().sub(s.p);
759:       const lateral = d.dot(s.r);
760:       const along = d.dot(s.t);
761:       let dist = s.s + along;
762:       if (dist < 0) dist += length;
763:       if (dist >= length) dist -= length;
764:       return { idx: bestIdx, lateral, s: dist, u: dist / length };
765:     },
766:     pointAt(dist) {
767:       let d = dist % length;
768:       if (d < 0) d += length;
769:       const idx = Math.min(count - 1, Math.floor(d / step));
770:       const s = samples[idx];
771:       const next = samples[(idx + 1) % count];
772:       const f = (d - idx * step) / step;
773:       return {
774:         p: s.p.clone().lerp(next.p, f),
775:         t: s.t.clone().lerp(next.t, f).normalize(),
776:         r: s.r.clone().lerp(next.r, f).normalize(),
777:         idx,
778:       };
779:     },
780:   };
