792:       const w = 0.42 * (1 - f * 0.85) * (i === 0 ? 0.4 : 1);
793:       const len = 3.4 * f;
794:       const y = -0.12 - f * f * 0.85;
795:       pos.push(len, y, -w, len, y, w);
