797:     for (let i = 0; i < segs; i++) {
798:       const a = i * 2;
799:       idx.push(a, a + 2, a + 1, a + 1, a + 2, a + 3);
800:     }
801:     const g = new THREE.BufferGeometry();
802:     g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
