840: function updatePlayer(game, dt) {
841:   const p = game.player;
842:   const c = controls();
843:   const track = game.track;
844:   const halfW = track.halfWidth;
845:   const n = track.nearest(p.pos, p.hintIdx);
846:   p.hintIdx = n.idx;
847:   p.lateral = n.lateral;
848:   p.offroad = Math.abs(n.lateral) > halfW - 0.2;
849: 
850:   // steering smoothing
851:   const steerTarget = c.steer;
852:   p.steerVis = damp(p.steerVis, steerTarget, steerTarget !== 0 ? 8 : 11, dt);
853: 
854:   const speed = p.vel.length();
855:   const fwd = new THREE.Vector2(-Math.sin(p.yaw), -Math.cos(p.yaw));
856:   const right = new THREE.Vector2(Math.cos(p.yaw), -Math.sin(p.yaw));
857:   let vf = p.vel.dot(fwd);
858:   let vl = p.vel.dot(right);
859: 
860:   // engine
861:   const maxSpeed = c.nitro && p.nitro > 0.01 && vf > 4 ? 76 : 63;
862:   const speedRatio = clamp(vf / maxSpeed, 0, 1);
863:   let accel = 0;
864:   if (c.throttle) {
865:     accel = 23.5 * Math.pow(1 - speedRatio, 0.55) + 4.2;
866:     if (p.offroad) accel *= 0.34;
867:   }
868:   if (c.nitro && p.nitro > 0.01 && vf > 4) {
869:     accel += 15.5 * Math.pow(1 - speedRatio * 0.7, 0.8);
870:     p.nitro = Math.max(0, p.nitro - dt * 0.27);
871:     p.boost = true;
872:   } else {
873:     p.boost = false;
874:     p.nitro = Math.min(1, p.nitro + dt * 0.055);
875:   }
